-- Studio skill authority, effect execution and RFID inheritance. The generated
-- description registry is appended by build-studio-skill-migration.mjs.
BEGIN;

CREATE OR REPLACE FUNCTION public.tcg_studio_owner_turn(p_battle uuid,p_player text)
RETURNS integer LANGUAGE sql STABLE SET search_path=public,pg_temp AS $$
 SELECT greatest(1,CASE WHEN p_player='p1' THEN player1_owner_turn ELSE player2_owner_turn END) FROM battle_sessions WHERE id=p_battle;
$$;

CREATE OR REPLACE FUNCTION public.tcg_studio_status(p_battle uuid,p_source uuid,p_target uuid,p_key text,p_amount integer,p_expiry text DEFAULT NULL,p_extra jsonb DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE src battle_cards%rowtype; dst battle_cards%rowtype; sid uuid; delta integer:=0; stat text;
BEGIN
 SELECT * INTO src FROM battle_cards WHERE id=p_source AND battle_id=p_battle;
 SELECT * INTO dst FROM battle_cards WHERE id=p_target AND battle_id=p_battle FOR UPDATE;
 IF src.id IS NULL OR dst.id IS NULL OR dst.zone NOT IN ('active','bench') OR coalesce(dst.current_hp,0)<=0 THEN RETURN jsonb_build_object('ok',false,'message','Target status sudah tidak tersedia.'); END IF;
 UPDATE battle_status_effects SET active=false WHERE battle_id=p_battle AND target_card_id=p_target AND status_key=p_key AND active AND metadata->>'studio_version'='2';
 SELECT * INTO dst FROM battle_cards WHERE id=p_target;
 stat:=CASE WHEN p_key IN ('studio_attack_buff','studio_attack_debuff') THEN 'attack' WHEN p_key IN ('studio_defense','studio_defense_debuff','studio_team_defense') THEN 'defense' END;
 IF stat='attack' THEN delta:=greatest(0,coalesce(dst.attack,0)+p_amount)-coalesce(dst.attack,0); UPDATE battle_cards SET attack=attack+delta WHERE id=p_target;
 ELSIF stat='defense' THEN delta:=greatest(0,coalesce(dst.defense,0)+p_amount)-coalesce(dst.defense,0); UPDATE battle_cards SET defense=defense+delta WHERE id=p_target; END IF;
 INSERT INTO battle_status_effects(battle_id,source_player,source_card_id,target_player,target_card_id,scope,status_key,value,stacks,max_stacks,active,remaining_turns,consume_on,metadata)
 VALUES(p_battle,src.player,p_source,dst.player,p_target,'card',p_key,jsonb_build_object('amount',abs(p_amount)),1,1,true,NULL,'{}',
   jsonb_build_object('studio_version',2,'stat',stat,'delta',delta,'expiry',p_expiry,'expires_player',src.player,'expires_owner_turn',public.tcg_studio_owner_turn(p_battle,src.player)+CASE WHEN p_expiry IN ('next_end','next_start') THEN 1 ELSE 0 END,'kind',CASE WHEN p_amount<0 OR p_key IN ('root','studio_silence_slot2','studio_mark','studio_attack_reduction') THEN 'debuff' ELSE 'buff' END)||coalesce(p_extra,'{}')) RETURNING id INTO sid;
 INSERT INTO battle_events(battle_id,type,source_player,target_player,card_id,payload) VALUES(p_battle,'status_applied',src.player,dst.player,p_source,jsonb_build_object('status_key',p_key,'target_card_id',p_target,'amount',abs(p_amount),'message',p_key||' '||abs(p_amount)));
 RETURN jsonb_build_object('ok',true,'type','add_status','result',jsonb_build_object('effect_type','add_status','status_key',p_key,'target_card_id',p_target,'target_player',dst.player,'value',jsonb_build_object('amount',abs(p_amount))));
END $$;

-- Add the same marks/reductions to ordinary targeted attacks.
CREATE OR REPLACE FUNCTION public.tcg_studio_attack_bonus(p_battle uuid,p_source uuid,p_target uuid)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE s record; result integer:=0; own_player text;
BEGIN
 SELECT player INTO own_player FROM battle_cards WHERE id=p_source AND battle_id=p_battle;
 FOR s IN SELECT * FROM battle_status_effects WHERE battle_id=p_battle AND active AND
 ((target_card_id=p_target AND source_player=own_player AND status_key='studio_mark') OR (target_card_id=p_source AND status_key='studio_attack_reduction')) FOR UPDATE LOOP
   result:=result+CASE WHEN s.status_key='studio_mark' THEN 1 ELSE -1 END*coalesce((s.value->>'amount')::integer,0);
   UPDATE battle_status_effects SET active=false WHERE id=s.id;
 END LOOP;
 RETURN result;
END $$;

-- The existing Ultimate rule ignores DEF and clears shields. Keep that rule.
CREATE OR REPLACE FUNCTION public.tcg_studio_ultimate_clear(p_battle uuid,p_target uuid,p_damage integer)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 UPDATE battle_status_effects SET active=false WHERE battle_id=p_battle AND target_card_id=p_target AND active AND status_key IN ('studio_shield','studio_reduction','studio_defense');
 RETURN p_damage;
END $$;

DO $patch$
DECLARE s text; patched text;
BEGIN
 IF to_regprocedure('public.tcg_apply_effects_pre_studio(uuid,text,uuid,jsonb,jsonb)') IS NULL THEN ALTER FUNCTION public.tcg_apply_effects(uuid,text,uuid,jsonb,jsonb) RENAME TO tcg_apply_effects_pre_studio; END IF;
 IF to_regprocedure('public.tcg_validate_effect_pre_studio(jsonb)') IS NULL THEN ALTER FUNCTION public.tcg_validate_effect_definition(jsonb) RENAME TO tcg_validate_effect_pre_studio; END IF;
 IF to_regprocedure('public.tcg_card_block_pre_studio(uuid,uuid,text)') IS NULL THEN ALTER FUNCTION public.tcg_card_action_block_reason(uuid,uuid,text) RENAME TO tcg_card_block_pre_studio; END IF;
 -- Extend the existing skill context without changing token/AP/CD handling.
 s:=pg_get_functiondef('public.process_special_skill(uuid,text,uuid,jsonb)'::regprocedure);
 IF position('skill_option' IN s)=0 THEN
   patched:=regexp_replace(s,'''action'',\s*''special_skill'',','''action'', ''special_skill'', ''skill_option'', p_payload->>''skill_option'', ''target_card_ids'', p_payload->''target_card_ids'', ''bench_card_id'', p_payload->>''bench_card_id'',');
   IF patched=s THEN RAISE EXCEPTION 'Unrecognized process_special_skill context; no changes applied.'; END IF; EXECUTE patched;
 END IF;
 -- Native attack damage must consume Studio shield/DEF on the same hit.
 s:=pg_get_functiondef('public.submit_battle_action_core_3d15(text,text,text,text,uuid,jsonb)'::regprocedure);
 IF position('tcg_studio_attack_bonus' IN s)=0 THEN
   patched:=regexp_replace(s,'v_attack_bonus\s*:=\s*0;','v_attack_bonus := public.tcg_studio_attack_bonus(v_battle.id,p_card_id,v_target_card_id);','g');
   IF patched=s THEN RAISE EXCEPTION 'Unrecognized native attack bonus.'; END IF; s:=patched;
   patched:=replace(s,'v_damage := v_final_damage;','v_final_damage := public.tcg_studio_absorb(v_battle.id,v_target_card_id,v_final_damage); v_damage := v_final_damage;');
   IF patched=s THEN RAISE EXCEPTION 'Unrecognized native attack damage.'; END IF; s:=patched;
   patched:=regexp_replace(s,'v_target_hp_after\s*:=\s*greatest\(\s*0,\s*v_target_hp_before - v_damage','v_damage := public.tcg_studio_ultimate_clear(v_battle.id,v_target_card.id,v_damage); v_target_hp_after := greatest(0, v_target_hp_before - v_damage');
   IF patched=s THEN RAISE EXCEPTION 'Unrecognized native ultimate damage.'; END IF; EXECUTE patched;
 END IF;
 s:=pg_get_functiondef('public.tcg_submit_active_combo_attack(text,text,text,uuid,uuid[],uuid)'::regprocedure);
 IF position('tcg_studio_absorb' IN s)=0 THEN
   patched:=replace(s,'v_hp_after := greatest(0,v_hp_before-v_damage);','v_damage := public.tcg_studio_absorb(v_battle.id,v_target.id,v_damage); v_hp_after := greatest(0,v_hp_before-v_damage);');
   IF patched=s THEN RAISE EXCEPTION 'Unrecognized combo damage.'; END IF; EXECUTE patched;
 END IF;
END $patch$;

CREATE OR REPLACE FUNCTION public.tcg_validate_effect_definition(p_effect jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$
BEGIN
 IF p_effect->>'type'='studio_skill' THEN RETURN jsonb_build_object('ok',jsonb_typeof(p_effect->'program')='object' AND p_effect#>>'{program,version}'='2'); END IF;
 RETURN public.tcg_validate_effect_pre_studio(p_effect);
END $$;

CREATE OR REPLACE FUNCTION public.tcg_card_action_block_reason(p_battle_id uuid,p_card_id uuid,p_action text)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE prior text;
BEGIN
 prior:=public.tcg_card_block_pre_studio(p_battle_id,p_card_id,p_action); IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF p_action IN ('attack','combo_attack','special_skill','ultimate') AND EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle_id AND target_card_id=p_card_id AND status_key='studio_revival_lock' AND active) THEN RETURN 'Kartu yang dibangkitkan baru dapat Attack/Skill pada giliran berikutnya.'; END IF;
 IF p_action IN ('switch_active','move_to_bench','return_from_bench') AND EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle_id AND target_card_id=p_card_id AND status_key='root' AND active) THEN RETURN 'Root: kartu tidak dapat melakukan Switch sukarela.'; END IF;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION public.tcg_apply_effects(p_battle_id uuid,p_source_player text,p_source_card_id uuid,p_effects jsonb,p_context jsonb DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE rule jsonb; runtime battle_card_skills%rowtype; result jsonb; reason text;
BEGIN
 IF jsonb_array_length(p_effects)=1 AND p_effects#>>'{0,type}'='studio_skill' THEN
   SELECT * INTO runtime FROM battle_card_skills WHERE id=public.tcg_try_uuid(p_context->>'battle_card_skill_id') AND battle_id=p_battle_id AND battle_card_id=p_source_card_id AND player=p_source_player;
   IF runtime.id IS NULL OR runtime.effects IS DISTINCT FROM p_effects THEN RETURN jsonb_build_object('ok',false,'message','Aturan skill runtime tidak cocok.'); END IF;
   reason:=public.tcg_card_action_block_reason(p_battle_id,p_source_card_id,'special_skill');
   IF reason IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'message',reason); END IF;
   IF runtime.metadata#>>'{master_metadata,slot}'='2' AND EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle_id AND target_card_id=p_source_card_id AND status_key='studio_silence_slot2' AND active) THEN RETURN jsonb_build_object('ok',false,'message','Skill 2 sedang dikunci.'); END IF;
   BEGIN
     result:=public.tcg_execute_studio_skill(p_battle_id,p_source_player,p_source_card_id,p_effects#>'{0,program}',p_context);
     RETURN result;
   EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'message',SQLERRM); END;
 END IF;
 RETURN public.tcg_apply_effects_pre_studio(p_battle_id,p_source_player,p_source_card_id,p_effects,p_context);
END $$;

CREATE OR REPLACE FUNCTION public.tcg_studio_restore_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF OLD.active AND NOT NEW.active AND OLD.metadata->>'studio_version'='2' THEN
   IF OLD.metadata->>'stat'='attack' THEN UPDATE battle_cards SET attack=greatest(0,attack-coalesce((OLD.metadata->>'delta')::integer,0)) WHERE id=OLD.target_card_id;
   ELSIF OLD.metadata->>'stat'='defense' THEN UPDATE battle_cards SET defense=greatest(0,defense-coalesce((OLD.metadata->>'delta')::integer,0)) WHERE id=OLD.target_card_id; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tbc_studio_restore_status ON public.battle_status_effects;
CREATE TRIGGER tbc_studio_restore_status AFTER UPDATE OF active ON public.battle_status_effects FOR EACH ROW EXECUTE FUNCTION public.tcg_studio_restore_status();

CREATE OR REPLACE FUNCTION public.tcg_studio_absorb(p_battle uuid,p_target uuid,p_damage integer)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE s record; remaining integer:=greatest(0,p_damage); absorbed integer; amount integer;
BEGIN
 FOR s IN SELECT * FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_target AND active AND metadata->>'studio_version'='2' AND status_key IN ('studio_shield','studio_reduction') ORDER BY CASE WHEN status_key='studio_reduction' THEN 0 ELSE 1 END,created_at,id FOR UPDATE LOOP
   amount:=greatest(0,coalesce((s.value->>'amount')::integer,0)); absorbed:=least(remaining,amount); remaining:=remaining-absorbed;
   IF s.status_key='studio_reduction' OR absorbed>=amount THEN UPDATE battle_status_effects SET active=false WHERE id=s.id;
   ELSE UPDATE battle_status_effects SET value=jsonb_build_object('amount',amount-absorbed) WHERE id=s.id; END IF;
 END LOOP;
 -- A DEF bonus lasts through the calculation of this hit, then expires.
 UPDATE battle_status_effects SET active=false WHERE battle_id=p_battle AND target_card_id=p_target AND active AND metadata->>'studio_version'='2' AND metadata->>'expiry'='hit' AND status_key='studio_defense';
 RETURN remaining;
END $$;

CREATE OR REPLACE FUNCTION public.tcg_studio_heal(p_battle uuid,p_target uuid,p_amount integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c battle_cards%rowtype; hp_after integer;
BEGIN
 SELECT * INTO c FROM battle_cards WHERE id=p_target AND battle_id=p_battle FOR UPDATE;
 IF c.id IS NULL OR c.zone NOT IN ('active','bench') OR coalesce(c.current_hp,0)<=0 THEN RETURN jsonb_build_object('ok',false,'message','Target heal sudah tidak hidup.'); END IF;
 hp_after:=least(coalesce(c.base_hp,c.hp),c.current_hp+greatest(0,p_amount));
 UPDATE battle_cards SET current_hp=hp_after WHERE id=c.id;
 RETURN jsonb_build_object('ok',true,'type','heal_card','result',jsonb_build_object('effect_type','heal_card','target_card_id',c.id,'target_player',c.player,'actual_heal',hp_after-c.current_hp,'hp_before',c.current_hp,'hp_after',hp_after));
END $$;

CREATE OR REPLACE FUNCTION public.tcg_studio_expire() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE s record; c battle_cards%rowtype; r jsonb;
BEGIN
 IF NEW.current_turn IS NOT DISTINCT FROM OLD.current_turn OR coalesce(current_setting('tcg.intra_turn_action',true),'off')='on' THEN RETURN NEW; END IF;
 FOR s IN SELECT * FROM battle_status_effects WHERE battle_id=NEW.id AND active AND metadata->>'studio_version'='2'
 AND ((metadata->>'expires_player'=OLD.current_turn AND metadata->>'expiry' IN ('end','next_end') AND (metadata->>'expires_owner_turn')::integer<=CASE WHEN OLD.current_turn='p1' THEN OLD.player1_owner_turn ELSE OLD.player2_owner_turn END)
 OR (metadata->>'expires_player'=NEW.current_turn AND metadata->>'expiry'='next_start' AND (metadata->>'expires_owner_turn')::integer<=CASE WHEN NEW.current_turn='p1' THEN NEW.player1_owner_turn ELSE NEW.player2_owner_turn END)) FOR UPDATE LOOP
   IF s.status_key='studio_delayed_heal' THEN
     r:=public.tcg_studio_heal(NEW.id,s.target_card_id,(s.value->>'amount')::integer);
     IF coalesce((r->>'ok')::boolean,false) THEN INSERT INTO battle_events(battle_id,type,source_player,target_player,card_id,payload) VALUES(NEW.id,'special_effect',s.source_player,s.target_player,s.source_card_id,jsonb_build_object('effect_type','heal_card','result',r->'result','message','Regeneration +'||(r#>>'{result,actual_heal}')||' HP')); END IF;
   END IF;
   UPDATE battle_status_effects SET active=false WHERE id=s.id;
 END LOOP;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tbc_studio_expire ON public.battle_sessions;
CREATE TRIGGER tbc_studio_expire AFTER UPDATE OF current_turn ON public.battle_sessions FOR EACH ROW EXECUTE FUNCTION public.tcg_studio_expire();

CREATE OR REPLACE FUNCTION public.tcg_studio_card_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t bigint; owner_turn integer; locked text;
BEGIN
 SELECT turn_index,public.tcg_studio_owner_turn(battle_sessions.id,NEW.player) INTO t,owner_turn FROM battle_sessions WHERE id=NEW.battle_id;
 IF TG_OP='INSERT' THEN
   IF NEW.zone='active' THEN NEW.battle_metadata:=coalesce(NEW.battle_metadata,'{}')||jsonb_build_object('studio_entered_turn',t,'studio_summoned_turn',t,'studio_actions',0); END IF;
 ELSIF NEW.zone IS DISTINCT FROM OLD.zone THEN
   IF NEW.zone IN ('active','bench') AND OLD.zone IN ('active','bench') THEN
     locked:=public.tcg_card_action_block_reason(NEW.battle_id,NEW.id,CASE WHEN OLD.zone='active' THEN 'move_to_bench' ELSE 'return_from_bench' END);
     IF locked IS NOT NULL THEN RAISE EXCEPTION '%',locked; END IF;
     NEW.battle_metadata:=coalesce(NEW.battle_metadata,'{}')||jsonb_build_object('studio_switched_turn',t);
   END IF;
   IF NEW.zone='active' THEN NEW.battle_metadata:=coalesce(NEW.battle_metadata,'{}')||jsonb_build_object('studio_entered_turn',t); END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tbc_studio_card_history ON public.battle_cards;
CREATE TRIGGER tbc_studio_card_history BEFORE INSERT OR UPDATE OF zone ON public.battle_cards FOR EACH ROW EXECUTE FUNCTION public.tcg_studio_card_history();

CREATE OR REPLACE FUNCTION public.tcg_studio_action_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NEW.card_id IS NOT NULL AND NEW.type IN ('attack','special_skill','defense','heal','synergy','ultimate','card_move') THEN
   UPDATE battle_cards SET battle_metadata=jsonb_set(coalesce(battle_metadata,'{}'),'{studio_actions}',to_jsonb(coalesce((battle_metadata->>'studio_actions')::integer,0)+1)) WHERE id=NEW.card_id AND battle_id=NEW.battle_id AND player=NEW.source_player;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tbc_studio_action_history ON public.battle_events;
CREATE TRIGGER tbc_studio_action_history AFTER INSERT ON public.battle_events FOR EACH ROW EXECUTE FUNCTION public.tcg_studio_action_history();

CREATE OR REPLACE FUNCTION public.tcg_studio_condition(p_battle uuid,p_source uuid,p_target uuid,p_condition text)
RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public,pg_temp AS $$
DECLARE c battle_cards%rowtype; t bigint;
BEGIN
 SELECT * INTO c FROM battle_cards WHERE id=p_source AND battle_id=p_battle;
 SELECT turn_index INTO t FROM battle_sessions WHERE id=p_battle;
 RETURN CASE p_condition
 WHEN 'always' THEN true
 WHEN 'ally_bench' THEN EXISTS(SELECT 1 FROM battle_cards WHERE battle_id=p_battle AND player=c.player AND id<>p_source AND zone='bench' AND current_hp>0)
 WHEN 'self_shield' THEN EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_source AND active AND status_key IN ('shield','water_shield','studio_shield'))
 WHEN 'target_no_shield' THEN NOT EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_target AND active AND status_key IN ('shield','water_shield','studio_shield'))
 WHEN 'first_summon_action' THEN (c.battle_metadata->>'studio_summoned_turn')::bigint=t AND coalesce((c.battle_metadata->>'studio_actions')::integer,0)=0
 WHEN 'entered_active' THEN (c.battle_metadata->>'studio_entered_turn')::bigint=t
 WHEN 'self_switched' THEN (c.battle_metadata->>'studio_switched_turn')::bigint=t
 WHEN 'ally_summoned' THEN EXISTS(SELECT 1 FROM battle_cards WHERE battle_id=p_battle AND player=c.player AND id<>p_source AND (battle_metadata->>'studio_summoned_turn')::bigint=t)
 WHEN 'ally_switched' THEN EXISTS(SELECT 1 FROM battle_cards WHERE battle_id=p_battle AND player=c.player AND id<>p_source AND (battle_metadata->>'studio_switched_turn')::bigint=t)
 WHEN 'target_root' THEN EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_target AND active AND status_key='root')
 WHEN 'target_burn' THEN EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_target AND active AND status_key='burn')
 WHEN 'target_debuff' THEN EXISTS(SELECT 1 FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_target AND active AND (status_key IN ('burn','poison','curse','freeze','stun','root') OR metadata->>'kind'='debuff'))
 WHEN 'ally_low_hp' THEN EXISTS(SELECT 1 FROM battle_cards WHERE battle_id=p_battle AND player=c.player AND id<>p_source AND zone IN ('active','bench') AND current_hp>0 AND current_hp<coalesce(base_hp,hp)*.5)
 WHEN 'self_high_hp' THEN c.current_hp>coalesce(c.base_hp,c.hp)*.5
 ELSE false END;
END $$;

 -- Studio programs execute inside process_special_skill's existing atomic
-- cooldown/usage ledger and submit_battle_action's token/AP/idempotency guard.
CREATE OR REPLACE FUNCTION public.tcg_execute_studio_skill(p_battle uuid,p_player text,p_source uuid,p_program jsonb,p_context jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE b battle_sessions%rowtype; src battle_cards%rowtype; dst battle_cards%rowtype; bench battle_cards%rowtype;
 operations jsonb:=p_program->'operations'; choice jsonb; item jsonb; r jsonb; results jsonb:='[]'; targets uuid[]; tid uuid; affected uuid; amount integer; bonus integer; power integer; damage integer; hp_after integer; player_damage integer; hp_before integer; mark record; s record; key text; expiry text; options jsonb; target_type text:=p_program->>'target';
BEGIN
 SELECT * INTO b FROM battle_sessions WHERE id=p_battle FOR UPDATE;
 SELECT * INTO src FROM battle_cards WHERE id=p_source AND battle_id=p_battle AND player=p_player AND zone='active' AND current_hp>0 FOR UPDATE;
 IF src.id IS NULL OR b.ruleset<>'tcg_v1' THEN RAISE EXCEPTION 'Kartu sumber tidak tersedia.'; END IF;
 tid:=public.tcg_try_uuid(p_context->>'target_card_id'); IF target_type='self_card' THEN tid:=p_source; END IF;
 targets:=ARRAY[tid];
 IF coalesce((p_program->>'max_targets')::integer,1)>1 AND jsonb_array_length(coalesce(p_context->'target_card_ids','[]'))>0 THEN targets:=ARRAY(SELECT jsonb_array_elements_text(p_context->'target_card_ids')::uuid); END IF;
 IF cardinality(targets)<1 OR cardinality(targets)>coalesce((p_program->>'max_targets')::integer,1) OR (SELECT count(DISTINCT id) FROM unnest(targets) id)<>cardinality(targets) THEN RAISE EXCEPTION 'Jumlah target tidak valid.'; END IF;
 FOREACH tid IN ARRAY targets LOOP
   SELECT * INTO dst FROM battle_cards WHERE id=tid AND battle_id=p_battle FOR UPDATE;
   IF dst.id IS NULL OR (target_type='enemy_active' AND (dst.player=p_player OR dst.zone<>'active' OR dst.current_hp<=0))
   OR (target_type IN ('ally_field','ally_active','ally_graveyard') AND dst.player<>p_player)
   OR (target_type='ally_field' AND (dst.zone NOT IN ('active','bench') OR dst.current_hp<=0))
   OR (target_type='ally_active' AND (dst.zone<>'active' OR dst.current_hp<=0))
   OR (target_type='ally_graveyard' AND dst.zone<>'graveyard') THEN RAISE EXCEPTION 'Target skill tidak valid.'; END IF;
 END LOOP;
 IF jsonb_array_length(p_program->'choices')>0 THEN
   SELECT value INTO choice FROM jsonb_array_elements(p_program->'choices') WHERE value->>'id'=p_context->>'skill_option';
   IF choice IS NULL THEN RAISE EXCEPTION 'Pilih satu efek skill terlebih dahulu.'; END IF; operations:=choice->'operations';
 END IF;
 -- Hydro Barrier and Cache Restore are mutually exclusive in either order.
 IF EXISTS(SELECT 1 FROM battle_card_skills WHERE battle_card_id=p_source AND effects#>>'{0,program,exclusive}'='true') AND EXISTS(SELECT 1 FROM battle_card_skills WHERE battle_card_id=p_source AND last_used_round=b.round AND last_used_turn_player=p_player) THEN RAISE EXCEPTION 'Cache Restore dan Hydro Barrier tidak boleh digunakan pada giliran yang sama.'; END IF;
 IF coalesce((p_program->>'attacks')::boolean,false) AND NOT public.tcg_battle_card_can_attack(p_source,b.turn_index,b.max_attacks_per_card) THEN RAISE EXCEPTION 'Kartu ini sudah mencapai batas serangan pada giliran ini.'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(operations) LOOP
   key:=item->>'type'; expiry:=item->>'expiry'; amount:=coalesce((item->>'amount')::numeric,0)::integer;
   FOREACH tid IN ARRAY targets LOOP
     affected:=CASE WHEN item->>'target'='self' THEN p_source ELSE tid END;
     SELECT * INTO dst FROM battle_cards WHERE id=affected AND battle_id=p_battle FOR UPDATE;
     IF key<>'attack' AND dst.zone='graveyard' AND key<>'revive' THEN CONTINUE; END IF;
     IF key='attack' THEN
       bonus:=CASE WHEN public.tcg_studio_condition(p_battle,p_source,tid,item->>'condition') THEN amount ELSE 0 END;
       SELECT * INTO src FROM battle_cards WHERE id=p_source;
       power:=greatest(0,round(src.attack*coalesce((item->>'multiplier')::numeric,1))::integer+bonus);
       -- The next normal ally attack consumes a mark only once.
       FOR mark IN SELECT * FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=tid AND source_player=p_player AND active AND status_key='studio_mark' FOR UPDATE LOOP power:=power+coalesce((mark.value->>'amount')::integer,0); UPDATE battle_status_effects SET active=false WHERE id=mark.id; END LOOP;
       FOR s IN SELECT * FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=p_source AND active AND status_key='studio_attack_reduction' FOR UPDATE LOOP power:=greatest(0,power-coalesce((s.value->>'amount')::integer,0)); UPDATE battle_status_effects SET active=false WHERE id=s.id; END LOOP;
       damage:=greatest(1,power-greatest(0,dst.defense));
       IF (CASE WHEN p_player='p1' THEN b.player1_power_strike_ready ELSE b.player2_power_strike_ready END) THEN damage:=greatest(1,round(damage*1.5)::integer); END IF;
       damage:=greatest(1,round(damage*(1-coalesce(CASE WHEN p_player='p1' THEN b.player1_attack_debuff ELSE b.player2_attack_debuff END,0)))::integer);
       IF (CASE WHEN dst.player='p1' THEN b.player1_defending ELSE b.player2_defending END) THEN damage:=greatest(1,round(damage*.5)::integer); END IF;
       damage:=greatest(1,round(damage*(1-coalesce(CASE WHEN dst.player='p1' THEN b.player1_synergy_shield ELSE b.player2_synergy_shield END,0)))::integer);
       damage:=public.tcg_studio_absorb(p_battle,tid,damage); hp_before:=dst.current_hp; hp_after:=greatest(0,hp_before-damage);
       UPDATE battle_cards SET current_hp=hp_after,zone=CASE WHEN hp_after=0 THEN 'graveyard' ELSE zone END,slot=CASE WHEN hp_after=0 THEN NULL ELSE slot END,exhausted=hp_after=0,destroyed_at=CASE WHEN hp_after=0 THEN now() ELSE destroyed_at END,graveyard_at=CASE WHEN hp_after=0 THEN now() ELSE graveyard_at END,graveyard_reason=CASE WHEN hp_after=0 THEN 'studio_skill' ELSE graveyard_reason END WHERE id=tid;
       player_damage:=0;
       IF hp_after=0 AND coalesce(b.destruction_damage_enabled,true) THEN player_damage:=round(CASE WHEN b.destruction_damage_mode='overflow_percent' THEN greatest(0,damage-hp_before) ELSE least(hp_before,damage) END*coalesce(b.destruction_damage_percent,.3))::integer; END IF;
       IF dst.player='p1' THEN UPDATE battle_sessions SET player1_hp=greatest(0,player1_hp-player_damage),player1_defending=false,player1_synergy_shield=0 WHERE id=p_battle;
       ELSE UPDATE battle_sessions SET player2_hp=greatest(0,player2_hp-player_damage),player2_defending=false,player2_synergy_shield=0 WHERE id=p_battle; END IF;
       r:=jsonb_build_object('ok',true,'type','damage_card','result',jsonb_build_object('effect_type','damage_card','target_card_id',tid,'target_player',dst.player,'actual_damage',least(hp_before,damage),'requested_damage',damage,'bonus_damage',bonus,'hp_before',hp_before,'hp_after',hp_after,'destroyed',hp_after=0,'player_damage',player_damage));
     ELSIF key='heal' THEN r:=public.tcg_studio_heal(p_battle,affected,amount);
     ELSIF key='cleanse' THEN
       SELECT * INTO s FROM battle_status_effects WHERE battle_id=p_battle AND target_card_id=affected AND active AND (status_key IN ('burn','poison','curse','freeze','stun','root') OR metadata->>'kind'='debuff') ORDER BY created_at,id LIMIT 1 FOR UPDATE;
       IF s.id IS NOT NULL THEN UPDATE battle_status_effects SET active=false WHERE id=s.id; END IF;
       r:=jsonb_build_object('ok',true,'type','remove_status','result',jsonb_build_object('effect_type','remove_status','target_card_id',affected,'removed',CASE WHEN s.id IS NULL THEN 0 ELSE 1 END));
     ELSIF key='burn' THEN
       PERFORM public.tcg_apply_combo_status(p_battle,p_player,p_source,affected,'burn',0,jsonb_build_object('source_trigger','studio_skill','tick_damage',coalesce((public.tcg_status_rule('burn')->>'tick_damage')::integer,10)));
       r:=jsonb_build_object('ok',true,'type','add_status','result',jsonb_build_object('effect_type','add_status','status_key','burn','target_card_id',affected,'value',jsonb_build_object('amount',1)));
     ELSIF key='switch' THEN
       SELECT * INTO bench FROM battle_cards WHERE id=public.tcg_try_uuid(p_context->>'bench_card_id') AND battle_id=p_battle AND player=p_player AND zone='bench' AND current_hp>0 AND NOT exhausted FOR UPDATE;
       IF bench.id IS NULL THEN RAISE EXCEPTION 'Pilih kartu Bench yang masih hidup untuk Switch.'; END IF;
       UPDATE battle_cards SET zone='bench',slot=NULL WHERE id=affected;
       UPDATE battle_cards SET zone='active',slot=dst.slot WHERE id=bench.id;
       r:=jsonb_build_object('ok',true,'type','move_zone','result',jsonb_build_object('effect_type','move_zone','target_card_id',affected,'bench_card_id',bench.id,'from_zone','active','to_zone','bench','cards_drawn',0));
       INSERT INTO battle_events(battle_id,type,source_player,card_id,payload) VALUES(p_battle,'card_move',p_player,affected,jsonb_build_object('action','switch_active','bench_card_id',bench.id,'active_card_id',affected,'message',dst.name||' ↔ '||bench.name));
     ELSIF key='revive' THEN
       IF dst.zone<>'graveyard' OR coalesce(dst.is_fusion_result,false) OR coalesce(dst.fusion_consumed,false) OR dst.origin_type='fusion' OR dst.card_kind='fusion' THEN RAISE EXCEPTION 'Necro Recall hanya untuk Base non-Fusion yang tidak dikonsumsi Fusion.'; END IF;
       IF (SELECT count(*) FROM battle_cards WHERE battle_id=p_battle AND player=p_player AND zone='bench' AND current_hp>0)>=coalesce(b.max_bench,4) THEN RAISE EXCEPTION 'Bench penuh.'; END IF;
       hp_after:=greatest(1,round(coalesce(dst.base_hp,dst.hp)*(item->>'amount')::numeric)::integer);
       UPDATE battle_cards SET zone='bench',slot=NULL,current_hp=hp_after,exhausted=false,destroyed_at=NULL,graveyard_at=NULL,graveyard_reason=NULL,revive_count=coalesce(revive_count,0)+1 WHERE id=affected;
       PERFORM public.tcg_studio_status(p_battle,p_source,affected,'studio_revival_lock',0,'next_start');
       r:=jsonb_build_object('ok',true,'type','revive','result',jsonb_build_object('effect_type','revive','target_card_id',affected,'target_player',p_player,'restored_hp',hp_after,'to_zone','bench'));
     ELSIF key='team_defense' THEN
       FOR s IN SELECT id FROM battle_cards WHERE battle_id=p_battle AND player=p_player AND zone IN ('active','bench') AND current_hp>0 LOOP results:=results||jsonb_build_array(public.tcg_studio_status(p_battle,p_source,s.id,'studio_team_defense',amount,expiry)); END LOOP; CONTINUE;
     ELSE
       r:=public.tcg_studio_status(p_battle,p_source,affected,CASE key WHEN 'root' THEN 'root' ELSE 'studio_'||key END,CASE WHEN key IN ('attack_debuff','defense_debuff') THEN -amount ELSE amount END,CASE WHEN key='root' THEN 'next_end' ELSE expiry END);
     END IF;
     IF NOT coalesce((r->>'ok')::boolean,false) THEN RAISE EXCEPTION '%',coalesce(r->>'message','Skill gagal diterapkan.'); END IF;
     results:=results||jsonb_build_array(r);
   END LOOP;
 END LOOP;
 IF coalesce((p_program->>'attacks')::boolean,false) THEN
   UPDATE battle_cards SET last_attacked_turn=b.turn_index,attacks_this_turn=CASE WHEN attack_turn_index=b.turn_index THEN coalesce(attacks_this_turn,0)+1 ELSE 1 END,attack_turn_index=b.turn_index WHERE id=p_source;
   IF p_player='p1' THEN UPDATE battle_sessions SET player1_power_strike_ready=false,player1_attack_debuff=0,player1_skill=least(100,coalesce(player1_skill,0)+10),player2_skill=least(100,coalesce(player2_skill,0)+5) WHERE id=p_battle;
   ELSE UPDATE battle_sessions SET player2_power_strike_ready=false,player2_attack_debuff=0,player2_skill=least(100,coalesce(player2_skill,0)+10),player1_skill=least(100,coalesce(player1_skill,0)+5) WHERE id=p_battle; END IF;
 END IF;
 UPDATE battle_sessions SET winner=CASE WHEN player1_hp<=0 THEN 'p2' WHEN player2_hp<=0 THEN 'p1' ELSE winner END,status=CASE WHEN player1_hp<=0 OR player2_hp<=0 THEN 'finished' ELSE status END,finished_at=CASE WHEN player1_hp<=0 OR player2_hp<=0 THEN now() ELSE finished_at END WHERE id=p_battle;
 RETURN jsonb_build_object('ok',true,'results',results,'effect_count',jsonb_array_length(results));
END $$;
-- BEGIN GENERATED STUDIO REGISTRY (build-studio-skill-migration.mjs)
CREATE OR REPLACE FUNCTION public.studio_default_skill_rule(p_description text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $registry$
DECLARE d text:=lower(regexp_replace(regexp_replace(trim(coalesce(p_description,'')), '\s+', ' ', 'g'),'[.;]+$','','g')); result jsonb; m text[]; n integer; cd integer;
BEGIN
 SELECT rules.rule INTO result FROM (VALUES
 ('serangan normal; +3 damage jika ada ally di bench','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"ally_bench","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"ally_bench","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('beri shield 8 ke 1 ally. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[{"type":"shield","amount":8}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[{"type":"shield","amount":8}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal; +3 damage jika diri memiliki shield','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"self_shield","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"self_shield","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('+4 def pada diri sampai menerima 1 hit. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"self_card","operations":[{"type":"defense","amount":4,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"self_card","required":false,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"self_card","operations":[{"type":"defense","amount":4,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal; +3 damage pada aksi pertama setelah summon','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"first_summon_action","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"first_summon_action","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('switch 1 ally sebagai aksi; tidak menarik kartu. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_active","operations":[{"type":"switch"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_active","required":true,"choices":[],"max_targets":1,"needs_bench":true},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_active","operations":[{"type":"switch"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal; +3 damage jika baru masuk active','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"entered_active","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":3,"condition":"entered_active","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('kurangi 7 damage dari hit berikutnya ke diri. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"self_card","operations":[{"type":"reduction","amount":7,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"self_card","required":false,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"self_card","operations":[{"type":"reduction","amount":7,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('pulihkan 7 hp pada 1 ally. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[{"type":"heal","amount":7}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[{"type":"heal","amount":7}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal dan menerapkan burn 1','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":0,"condition":"always","multiplier":1},{"type":"burn","amount":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":0,"condition":"always","multiplier":1},{"type":"burn","amount":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('+4 def pada 1 ally sampai menerima 1 hit. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[{"type":"defense","amount":4,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[{"type":"defense","amount":4,"expiry":"hit"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal +6 setelah kamu summon ally. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":6,"condition":"ally_summoned","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":6,"condition":"ally_summoned","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('pilih: heal 12 pada 1 ally atau +4 def sampai 1 hit. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[],"choices":[{"id":"heal","label":"Pulihkan 12 HP","operations":[{"type":"heal","amount":12}]},{"id":"defense","label":"+4 DEF · 1 hit","operations":[{"type":"defense","amount":4,"expiry":"hit"}]}],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[{"id":"heal","label":"Pulihkan 12 HP"},{"id":"defense","label":"+4 DEF · 1 hit"}],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[],"choices":[{"id":"heal","label":"Pulihkan 12 HP","operations":[{"type":"heal","amount":12}]},{"id":"defense","label":"+4 DEF · 1 hit","operations":[{"type":"defense","amount":4,"expiry":"hit"}]}],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal +6 setelah ally melakukan switch legal. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":6,"condition":"ally_switched","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":6,"condition":"ally_switched","multiplier":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('beri shield 10 ke 1 ally. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[{"type":"shield","amount":10}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[{"type":"shield","amount":10}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('serangan normal; target tidak dapat melakukan switch sukarela sampai akhir turn berikutnya. cd 2','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":0,"condition":"always","multiplier":1},{"type":"root","amount":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"enemy_active","required":true,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":2,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"enemy_active","operations":[{"type":"attack","amount":0,"condition":"always","multiplier":1},{"type":"root","amount":1}],"choices":[],"attacks":true,"max_targets":1,"exclusive":false}}]}'::jsonb),
