 ('sekali/battle pilih 1: heal 18, shield 18, atau +8 atk pada 1 ally sampai akhir turn','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"ally_field","operations":[],"choices":[{"id":"heal","label":"Pulihkan 18 HP","operations":[{"type":"heal","amount":18}]},{"id":"shield","label":"Shield 18","operations":[{"type":"shield","amount":18}]},{"id":"attack","label":"+8 ATK · akhir giliran","operations":[{"type":"attack_buff","amount":8,"expiry":"end"}]}],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"ally_field","required":true,"choices":[{"id":"heal","label":"Pulihkan 18 HP"},{"id":"shield","label":"Shield 18"},{"id":"attack","label":"+8 ATK · akhir giliran"}],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":0,"action_points":1,"once_per_battle":true},"effects":[{"type":"studio_skill","program":{"version":2,"target":"ally_field","operations":[],"choices":[{"id":"heal","label":"Pulihkan 18 HP","operations":[{"type":"heal","amount":18}]},{"id":"shield","label":"Shield 18","operations":[{"type":"shield","amount":18}]},{"id":"attack","label":"+8 ATK · akhir giliran","operations":[{"type":"attack_buff","amount":8,"expiry":"end"}]}],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb),
 ('active dan bench mendapat +3 def sampai awal turn berikutnya. cd 3','{"enabled":true,"behavior":"auto","version":2,"program":{"version":2,"target":"self_card","operations":[{"type":"team_defense","amount":3,"expiry":"next_start"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false},"activation_timing":"main_phase","source_zones":["active"],"consumes_turn":false,"cost_spec":{"type":"none"},"target_spec":{"type":"self_card","required":false,"choices":[],"max_targets":1,"needs_bench":false},"limits":{"cooldown_turns":3,"action_points":1,"once_per_battle":false},"effects":[{"type":"studio_skill","program":{"version":2,"target":"self_card","operations":[{"type":"team_defense","amount":3,"expiry":"next_start"}],"choices":[],"attacks":false,"max_targets":1,"exclusive":false}}]}'::jsonb)
 ) AS rules(description,rule) WHERE rules.description=d;
 IF result IS NOT NULL THEN RETURN result; END IF;
 -- Custom single-effect skills use exact complete patterns, with bounded values.
 m:=regexp_match(d,'^pulihkan ([0-9]{1,3}) hp pada 1 ally(?:\. cd ([0-9]{1,2}))?$');
 IF m IS NOT NULL THEN
  result:=public.studio_default_skill_rule('Pulihkan 7 HP pada 1 ally. CD 2.');
 ELSE
  m:=regexp_match(d,'^beri shield ([0-9]{1,3}) (?:ke|pada) 1 ally(?:\. cd ([0-9]{1,2}))?$');
  IF m IS NOT NULL THEN result:=public.studio_default_skill_rule('Beri Shield 8 ke 1 ally. CD 2.');
  ELSE
   m:=regexp_match(d,'^\+([0-9]{1,3}) def pada diri sampai menerima 1 hit(?:\. cd ([0-9]{1,2}))?$');
   IF m IS NOT NULL THEN result:=public.studio_default_skill_rule('+4 DEF pada diri sampai menerima 1 hit. CD 2.'); END IF;
  END IF;
 END IF;
 IF result IS NULL THEN RETURN jsonb_build_object('version',2,'behavior','auto','enabled',false,'reason','Deskripsi belum didukung oleh engine. Atur aturan di Skill & Catalog.','effects','[]'::jsonb); END IF;
 n:=m[1]::integer; cd:=coalesce(m[2]::integer,0);
 IF n<1 OR cd>20 THEN RAISE EXCEPTION 'Nilai efek atau cooldown tidak valid.'; END IF;
 result:=jsonb_set(result,'{program,operations,0,amount}',to_jsonb(n));
 result:=jsonb_set(result,'{effects,0,program}',result->'program');
 RETURN jsonb_set(result,'{limits,cooldown_turns}',to_jsonb(cd));
END $registry$;
-- END GENERATED STUDIO REGISTRY

CREATE OR REPLACE FUNCTION public.sync_studio_battle_skills(p_game_card_id uuid,p_skills jsonb,p_artwork jsonb DEFAULT '{}')
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE skill jsonb; rule jsonb; slot integer:=0; sid uuid; v_code text; enabled boolean; active_count integer:=0;
BEGIN
 IF p_game_card_id IS NULL OR jsonb_typeof(p_skills) IS DISTINCT FROM 'array' OR jsonb_array_length(p_skills)<>2 THEN RAISE EXCEPTION 'Skill Studio harus tepat dua slot.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('studio-skills:'||p_game_card_id::text,0));
 FOR skill IN SELECT value FROM jsonb_array_elements(p_skills) LOOP
   slot:=slot+1; rule:=public.studio_default_skill_rule(skill->>'description');
   enabled:=coalesce((rule->>'enabled')::boolean,false) AND coalesce((skill#>>'{battle,enabled}')::boolean,true);
   v_code:='studio_'||replace(p_game_card_id::text,'-','')||'_'||slot;
   INSERT INTO special_skills(code,name,description,icon,category,skill_type,activation_timing,source_zones,target_spec,cost_spec,limits,effects,consumes_turn,priority,is_active,catalog_status,metadata)
   VALUES(v_code,coalesce(nullif(trim(skill->>'name'),''),'Skill '||slot),skill->>'description',p_artwork#>>ARRAY['skill_icons',(slot-1)::text,'url'],'studio_card','active','main_phase',ARRAY['active'],coalesce(rule->'target_spec','{}'),'{"type":"none"}',coalesce(rule->'limits','{}'),coalesce(rule->'effects','[]'),false,slot,enabled,CASE WHEN enabled THEN 'active' ELSE 'draft' END,jsonb_build_object('studio_generated',true,'studio_version',2,'studio_card_id',p_game_card_id,'studio_rule',rule,'slot',slot,'rules_status',CASE WHEN enabled THEN 'executable' ELSE 'configuration_required' END))
   ON CONFLICT(code) DO UPDATE SET name=excluded.name,description=excluded.description,icon=excluded.icon,target_spec=excluded.target_spec,cost_spec=excluded.cost_spec,limits=excluded.limits,effects=excluded.effects,is_active=excluded.is_active,catalog_status=excluded.catalog_status,metadata=excluded.metadata,updated_at=now() RETURNING id INTO sid;
   INSERT INTO game_card_special_skills(game_card_id,special_skill_id,sort_order,enabled,overrides) VALUES(p_game_card_id,sid,slot,enabled,'{}') ON CONFLICT(game_card_id,special_skill_id) DO UPDATE SET sort_order=excluded.sort_order,enabled=excluded.enabled;
   IF enabled THEN active_count:=active_count+1; END IF;
 END LOOP;
 RETURN active_count;
END $$;

-- Saving a template and its executable skills is one transaction. Physical
-- copies carry the printed data and get the same two authoritative programs.
CREATE OR REPLACE FUNCTION public.tcg_studio_card_saved() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF jsonb_typeof(NEW.metadata#>'{studio_card,skills}')='array' THEN
   PERFORM public.sync_studio_battle_skills(NEW.id,NEW.metadata#>'{studio_card,skills}',NEW.metadata->'studio_artwork');
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tbc_studio_card_saved ON public.game_cards;
CREATE TRIGGER tbc_studio_card_saved AFTER INSERT OR UPDATE OF metadata ON public.game_cards FOR EACH ROW EXECUTE FUNCTION public.tcg_studio_card_saved();

CREATE OR REPLACE FUNCTION public.sync_card_studio_battle_skills(p_dataset text,p_card_keys text[] DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE owner uuid:=auth.uid(); c record; n integer:=0; total integer:=0;
BEGIN
 IF owner IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Admin login diperlukan.' USING ERRCODE='42501'; END IF;
 FOR c IN SELECT g.id,g.metadata FROM card_studio_entries e JOIN game_cards g ON g.id=e.game_card_id WHERE e.owner_id=owner AND e.dataset_id=p_dataset AND (p_card_keys IS NULL OR e.card_key=ANY(p_card_keys)) LOOP
   n:=n+public.sync_studio_battle_skills(c.id,c.metadata#>'{studio_card,skills}',c.metadata->'studio_artwork'); total:=total+2;
 END LOOP;
 RETURN jsonb_build_object('synced_slots',n,'pending_slots',total-n);
END $$;

-- Backfill current masters/copies only. Existing battles keep their immutable
-- snapshots, usage counters and cooldown; rules become available on new entry.
DO $$ DECLARE c record; BEGIN
 FOR c IN SELECT id,metadata FROM game_cards WHERE jsonb_typeof(metadata#>'{studio_card,skills}')='array' LOOP
   PERFORM public.sync_studio_battle_skills(c.id,c.metadata#>'{studio_card,skills}',c.metadata->'studio_artwork');
 END LOOP;
END $$;

-- All effect helpers are internal; only the account-scoped admin sync is RPC.
DO $$ DECLARE p record; BEGIN
 FOR p IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND (proname LIKE 'tcg_studio_%' OR proname IN ('tcg_execute_studio_skill','sync_studio_battle_skills','studio_default_skill_rule','tcg_apply_effects_pre_studio','tcg_validate_effect_pre_studio','tcg_card_block_pre_studio','tcg_apply_effects','tcg_validate_effect_definition','tcg_card_action_block_reason')) LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',p.signature);
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.sync_card_studio_battle_skills(text,text[]) FROM PUBLIC,anon;
